import requests

url = "https://api.themoviedb.org/3/search/movie"
params = {"query": "Avatar", "include_adult": "false"}
response = requests.get(url, params=params)
response.raise_for_status()

movies = response.json().get("results", [])
titles = {"Avatar", "Avatar: The Way of Water"}
ratings = {
    movie["title"]: movie.get("vote_average", 0)
    for movie in movies
    if movie.get("title") in titles
}

for title, rating in ratings.items():
    print(f"{title}: {rating}")

if len(ratings) == 2:
    higher_rated = max(ratings, key=ratings.get)
    print(f"Higher rating: {higher_rated}")

