import requests

BASE_URL = "https://api.themoviedb.org/3"
API_KEY = "YOUR_TMDB_API_KEY"

def get_directed_movie_count(name):
    response = requests.get(
        f"{BASE_URL}/search/person",
        params={"api_key": API_KEY, "query": name},
    )
    response.raise_for_status()
    people = response.json().get("results", [])
    if not people:
        return name, 0

    person = people[0]
    credits_response = requests.get(
        f"{BASE_URL}/person/{person['id']}/movie_credits",
        params={"api_key": API_KEY},
    )
    credits_response.raise_for_status()

    directed_movies = {
        credit["id"]
        for credit in credits_response.json().get("crew", [])
        if credit.get("job") == "Director"
    }
    return person.get("name", name), len(directed_movies)

kurosawa_name, kurosawa_count = get_directed_movie_count("Akira Kurosawa")
spielberg_name, spielberg_count = get_directed_movie_count("Steven Spielberg")

print(f"{kurosawa_name}: {kurosawa_count} movies directed")
print(f"{spielberg_name}: {spielberg_count} movies directed")

if kurosawa_count > spielberg_count:
    print(f"{kurosawa_name} directed more movies.")
elif spielberg_count > kurosawa_count:
    print(f"{spielberg_name} directed more movies.")
else:
    print("They directed the same number of movies.")

